751	export function triggerListeners<T extends keyof MapListeners>(
752	  type: T,
753	  editor: LexicalEditor,
754	  isCurrentlyEnqueuingUpdates: boolean,
755	  ...payload: MapListeners[T]
756	): void {
757	  const previouslyUpdating = editor._updating;
758	  editor._updating = isCurrentlyEnqueuingUpdates;
759	
760	  try {
761	    const listenerMap = editor._listeners[type] as Map<
762	      (...args: MapListeners[T]) => void | undefined | (() => void),
763	      void | undefined | (() => void)
764	    >;
765	    const listeners = Array.from(listenerMap);
766	    for (const [listener, unregister] of listeners) {
767	      if (unregister) {
768	        unregister();
769	      }
770	      const nextUnregister = listener(...payload);
771	      if (listenerMap.has(listener)) {
772	        listenerMap.set(listener, nextUnregister);
773	      } else if (nextUnregister) {
774	        nextUnregister();
775	      }
776	    }
777	  } finally {
778	    editor._updating = previouslyUpdating;
779	  }
780	}
